          Schedule
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="block text-sm font-medium text-foreground">Start Time *</label>
            <Input
              type="datetime-local"
              value={formData.start_time}
