import { useState, useEffect } from 'react'
import { Button } from './ui/button'
import {
  Calendar,
  Clock,
  MapPin,
  Users,
  Edit,
  ArrowLeft,
  AlertTriangle,
  Repeat,
  Info,
  Shield
} from 'lucide-react'
import { motion } from 'framer-motion'
import { api, type ApiEvent } from '../lib/api'

