      setLoading(true)
      setError(null)

      // Fetch event details
      const eventData = await api.fetchEvent(eventId)
      setEvent(eventData)

      // Fetch team details for the team IDs
      if (eventData.team_ids && eventData.team_ids.length > 0) {
        await fetchTeamDetails(eventData.team_ids)
      }
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to load event details'
      setError(errorMessage)
      console.error('Error fetching event details:', err)
    } finally {
      setLoading(false)
    }
  }

  const fetchTeamDetails = async (teamIds: number[]) => {
    try {
      const response = await fetch('/api/teams')
      if (!response.ok) {
        throw new Error('Failed to fetch teams')
      }
      const data = await response.json()
      const allTeams = data.teams || data

      // Filter teams to only include those in the event
      const eventTeams = allTeams.filter((team: Team) => teamIds.includes(team.id))
      setTeams(eventTeams)
    } catch (err) {
      console.error('Error fetching team details:', err)
      // Don't set error here as event details are more important
      setTeams([])
    }
  }

  const getEventTypeColor = (type: string) => {
    switch (type.toLowerCase()) {
      case 'game':
        return 'from-blue-600 to-blue-700'
      case 'practice':
        return 'from-green-600 to-green-700'
      case 'meeting':
        return 'from-purple-600 to-purple-700'
      case 'tournament':
        return 'from-red-600 to-red-700'
      case 'other':
        return 'from-gray-600 to-gray-700'
      default:
        return 'from-gray-600 to-gray-700'
    }
  }

  const getEventTypeIcon = (type: string) => {
    switch (type.toLowerCase()) {
      case 'game':
        return Users
      case 'practice':
        return Calendar
      case 'meeting':
        return Info
      case 'tournament':
        return Shield
      default:
        return Calendar
    }
  }

  const formatDateTime = (dateTimeString: string) => {
    const date = new Date(dateTimeString)
    return {
      date: date.toLocaleDateString('en-US', {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric'
      }),
      time: date.toLocaleTimeString('en-US', {
        hour: '2-digit',
        minute: '2-digit',
        hour12: true
      })
    }
  }

  const formatRecurrenceRule = (rule: string) => {
    switch (rule.toUpperCase()) {
      case 'DAILY':
        return 'Daily'
      case 'WEEKLY':
        return 'Weekly'
      case 'BIWEEKLY':
        return 'Every 2 weeks'
      case 'MONTHLY':
        return 'Monthly'
      default:
        return rule
    }
  }

  const calculateNextOccurrence = (startTime: string, recurrenceRule: string) => {
    const baseDate = new Date(startTime)
    const now = new Date()

    if (baseDate > now) {
      return baseDate // Event hasn't occurred yet
    }

    let nextDate = new Date(baseDate)

    switch (recurrenceRule.toUpperCase()) {
      case 'DAILY':
        while (nextDate <= now) {
          nextDate.setDate(nextDate.getDate() + 1)
        }
        break
      case 'WEEKLY':
        while (nextDate <= now) {
          nextDate.setDate(nextDate.getDate() + 7)
        }
        break
      case 'BIWEEKLY':
        while (nextDate <= now) {
          nextDate.setDate(nextDate.getDate() + 14)
        }
        break
      case 'MONTHLY':
        while (nextDate <= now) {
          nextDate.setMonth(nextDate.getMonth() + 1)
        }
        break
      default:
        return null
    }

    return nextDate
